
USE StayEase;

-- 1. Display complete booking details with customer and hotel information
SELECT
    b.BookingID,
    c.FullName AS CustomerName,
    h.HotelName,
    hb.BranchName,
    b.CheckInDate,
    b.CheckOutDate,
    b.BookingStatus
FROM Booking b
JOIN Customer c ON b.CustomerID = c.CustomerID
JOIN HotelBranch hb ON b.BranchID = hb.BranchID
JOIN Hotel h ON hb.HotelID = h.HotelID;

-- 2. Calculate total revenue generated by each hotel
SELECT
    h.HotelName,
    SUM(p.Amount) AS TotalRevenue
FROM Hotel h
JOIN HotelBranch hb ON h.HotelID = hb.HotelID
JOIN Booking b ON hb.BranchID = b.BranchID
JOIN Payment p ON b.BookingID = p.BookingID
WHERE p.PaymentStatus = 'SUCCESS'
GROUP BY h.HotelID, h.HotelName;

-- 3. Find the most popular room types based on bookings
SELECT
    rt.TypeName,
    COUNT(*) AS TotalBookings
FROM RoomType rt
JOIN Room r ON rt.RoomTypeID = r.RoomTypeID
JOIN BookingRoom br ON r.RoomID = br.RoomID
GROUP BY rt.RoomTypeID, rt.TypeName
ORDER BY TotalBookings DESC;

-- 4. Calculate total spending by each customer
SELECT
    c.CustomerID,
    c.FullName,
    COALESCE(SUM(
        CASE WHEN p.PaymentStatus = 'SUCCESS'
             THEN p.Amount ELSE 0 END
    ), 0) AS TotalSpent
FROM Customer c
LEFT JOIN Booking b ON c.CustomerID = b.CustomerID
LEFT JOIN Payment p ON b.BookingID = p.BookingID
GROUP BY c.CustomerID, c.FullName
ORDER BY TotalSpent DESC;

-- 5. Display branch-wise room inventory
SELECT
    hb.BranchName,
    COUNT(r.RoomID) AS TotalRooms,
    SUM(CASE WHEN r.RoomStatus = 'ACTIVE' THEN 1 ELSE 0 END) AS ActiveRooms,
    SUM(CASE WHEN r.RoomStatus = 'MAINTENANCE' THEN 1 ELSE 0 END) AS MaintenanceRooms
FROM HotelBranch hb
LEFT JOIN Room r ON hb.BranchID = r.BranchID
GROUP BY hb.BranchID, hb.BranchName;

-- 6. Find active rooms that have no booking allocation
SELECT
    r.RoomID,
    r.RoomNumber,
    hb.BranchName
FROM Room r
JOIN HotelBranch hb ON r.BranchID = hb.BranchID
WHERE r.RoomStatus = 'ACTIVE'
AND NOT EXISTS (
    SELECT 1
    FROM BookingRoom br
    JOIN Booking b ON br.BookingID = b.BookingID
    WHERE br.RoomID = r.RoomID
    AND b.BookingStatus IN ('PENDING', 'CONFIRMED')
);

-- 7. Calculate the duration of each booking
SELECT
    BookingID,
    DATEDIFF(CheckOutDate, CheckInDate) AS NumberOfNights
FROM Booking;

-- 8. Find bookings with outstanding or pending payments
SELECT
    b.BookingID,
    c.FullName,
    p.Amount,
    p.PaymentStatus
FROM Booking b
JOIN Customer c ON b.CustomerID = c.CustomerID
JOIN Payment p ON b.BookingID = p.BookingID
WHERE p.PaymentStatus = 'PENDING';

-- 9. Find customers who have given reviews
SELECT
    c.FullName,
    r.Rating,
    r.Comments,
    r.ReviewDate
FROM Customer c
JOIN Booking b ON c.CustomerID = b.CustomerID
JOIN Review r ON b.BookingID = r.BookingID;

-- 10. Calculate average customer rating for each hotel
SELECT
    h.HotelName,
    AVG(r.Rating) AS AverageRating,
    COUNT(r.ReviewID) AS TotalReviews
FROM Hotel h
JOIN HotelBranch hb ON h.HotelID = hb.HotelID
JOIN Booking b ON hb.BranchID = b.BranchID
JOIN Review r ON b.BookingID = r.BookingID
GROUP BY h.HotelID, h.HotelName;

-- 11. Calculate total successful revenue by payment method
SELECT
    PaymentMethod,
    SUM(Amount) AS TotalRevenue
FROM Payment
WHERE PaymentStatus = 'SUCCESS'
GROUP BY PaymentMethod
ORDER BY TotalRevenue DESC;

-- 12. Find customers with above-average spending
SELECT
    c.CustomerID,
    c.FullName,
    SUM(p.Amount) AS TotalSpent
FROM Customer c
JOIN Booking b ON c.CustomerID = b.CustomerID
JOIN Payment p ON b.BookingID = p.BookingID
WHERE p.PaymentStatus = 'SUCCESS'
GROUP BY c.CustomerID, c.FullName
HAVING SUM(p.Amount) > (
    SELECT AVG(CustomerTotal)
    FROM (
        SELECT SUM(p2.Amount) AS CustomerTotal
        FROM Booking b2
        JOIN Payment p2 ON b2.BookingID = p2.BookingID
        WHERE p2.PaymentStatus = 'SUCCESS'
        GROUP BY b2.CustomerID
    ) AS CustomerSpending
);

-- 13. Display bookings with their total service charges
SELECT
    b.BookingID,
    COALESCE(SUM(bs.Quantity * bs.UnitPrice), 0) AS TotalServiceCharges
FROM Booking b
LEFT JOIN BookingService bs ON b.BookingID = bs.BookingID
GROUP BY b.BookingID;

-- 14. Find the most frequently booked hotel branch
SELECT
    hb.BranchName,
    COUNT(b.BookingID) AS TotalBookings
FROM HotelBranch hb
JOIN Booking b ON hb.BranchID = b.BranchID
GROUP BY hb.BranchID, hb.BranchName
ORDER BY TotalBookings DESC
LIMIT 1;

-- 15. Calculate monthly successful payment revenue
SELECT
    DATE_FORMAT(PaymentDate, '%Y-%m') AS RevenueMonth,
    SUM(Amount) AS MonthlyRevenue
FROM Payment
WHERE PaymentStatus = 'SUCCESS'
GROUP BY DATE_FORMAT(PaymentDate, '%Y-%m')
ORDER BY RevenueMonth;
